        if(_tos.length == 0) return false;
        bytes4 id = bytes4(keccak256("transferFrom(address,address,uint256)"));

        for(uint i=0; i<_tos.length; i++){
            { (bool _s,) = caddress.call(abi.encodeWithSelector(id, from, _tos[i], v[i])); require(_s); }
        }

        return true;
    }

