pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, uint8 len) public {
        uint256 n = bound(len, 0, 7);

        address[] memory tos = new address[](n);
        uint[] memory vals = new uint[](n);

        for (uint i = 0; i < n; i++) {
            SimpleCallee callee = new SimpleCallee();
            tos[i] = address(callee);
            vals[i] = 1;
        }

        bool ok;
        try c.transfer(from, address(0xDEAD), tos, vals) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            bytes memory payload = abi.encodeWithSelector(bytes4(keccak256("transfer(address,address,address[],uint256[])")), from, address(0xDEAD), tos, vals);
            (bool success, bytes memory ret) = address(c).call(payload);
            require(success);
            bool retBool = abi.decode(ret, (bool));
            assertTrue(retBool);
        } else {
            if (n > 0) {
                revert("Unexpected revert for n>0 with well-behaved callees");
            }
        }
    }
}

